+fn rustup_dist_var(tv: &ToolVersion, key: &str) -> Option<String> {
+    match tv.install_env().shift_remove(key) {
+        Some(value) => value.into_string(),
+        None => env::var(key).ok(),
+    }
+    .map(|value| value.trim().to_string())
