+        let path = url
+            .to_file_path()
+            .map_err(|_| eyre::eyre!("invalid rustup file URL: {url}"))?;
+        return file::read_to_string(&path).wrap_err_with(|| {
+            format!("failed to read Rust channel manifest at {}", path.display())
+        });
+    }
+    HTTP_FETCH.get_text_cached(url).await
